      "output": "(()=>{\nconst F=window.F,T3=F.THREE,S=F.SHEET,L=S.look,D=L.device,P=S.palette,M=S.modules.find(m=>m.id==='device');\nconst sh=S.shots,mine=sh.filter(s=>M.scenes.includes(s.id)),s3=mine[mine.length-1];\nconst t0=Math.min(...mine.map(s=>s.start)),tEnd=(sh.find(s=>s.module==='type')||sh[sh.length-1]).start;\nconst rm=/rotation\\.y 0 to ([\\d.]+)/.exec(s3.picture),ROT=rm?+rm[1]:0.349;\nconst C=D.center,[sw,shh]=D.screenSize,bz=D.bezel,dp=D.depth,bw=sw+2*bz,bh=shh+2*bz;\nconst col=c=>new T3.Color(c);\nconst rr=(w,h,r)=>{const s=new T3.Shape(),x=-w/2,y=-h/2;s.moveTo(x+r,y);s.lineTo(x+w-r,y);s.quadraticCurveTo(x+w,y,x+w,y+r);s.lineTo(x+w,y+h-r);s.quadraticCurveTo(x+w,y+h,x+w-r,y+h);s.lineTo(x+r,y+h);s.quadraticCurveTo(x,y+h,x,y+h-r);s.lineTo(x,y+r);s.quadraticCurveTo(x,y,x+r,y);return s};\nlet dev,glass;\nF.scene('device',{start:t0,end:tEnd,setup(root){\nconst E=D.edge,G=D.glass,st=D.stand,fl=L.floor;\nconst mBody=new T3.MeshStandardMaterial({color:col(P.body),roughness:0.5,metalness:0.2});\nconst mEdge=new T3.MeshStandardMaterial({color:col(E.color),metalness:E.metalness,roughness:E.roughness});\nglass=new T3.MeshPhysicalMaterial({color:col('#000000'),roughness:0.45,metalness:G.metalness,clearcoat:0,specularIntensity:0.15,emissive:col(P.screenGround),emissiveIntensity:G.emissiveIntensity});\ndev=new T3.Group();dev.position.set(C[0],C[1],C[2]);root.add(dev);\nconst bg=new T3.ExtrudeGeometry(rr(bw,bh,0.025),{depth:dp,bevelEnabled:false,curveSegments:5});bg.translate(0,0,-dp/2);\ndev.add(new T3.Mesh(bg,[mBody,mEdge]));\nconst sm=new T3.Mesh(new T3.PlaneGeometry(sw,shh),glass);sm.position.z=dp/2+0.001;dev.add(sm);F.screenMesh=sm;\nconst ft=st.foot,nk=st.neck,fy=st.footY-C[1],nb=fy+ft[1]/2;\n[[ft,[0,fy,-dp/2-nk[2]-ft[2]/2+0.06]],[nk,[0,nb+nk[1]/2,-dp/2-nk[2]/2]]].forEach(([s,p])=>{const m=new T3.Mesh(new T3.BoxGeometry(s[0],s[1],s[2]),mEdge);m.position.set(p[0],p[1],p[2]);dev.add(m)});\nconst fg=new T3.Mesh(new T3.PlaneGeometry(fl.size,fl.size),new T3.MeshStandardMaterial({color:col(fl.color),roughness:0.7,metalness:fl.metalness}));\nfg.rotation.x=-Math.PI/2;fg.position.y=fl.y;root.add(fg);\n[L.keyLight,L.rimLight].forEach(k=>{const l=new T3.DirectionalLight(col(k.color),k.intensity);l.position.set(...k.position);root.add(l)});\nconst h=L.fillLight;root.add(new T3.HemisphereLight(col(h.sky),col(h.ground),h.intensity));\n},update(T){\nconst b=D.floatBob,ph=2*Math.PI*T/(b.periodBeats*F.BEAT);\ndev.position.set(C[0],C[1]+b.amplitude*Math.sin(ph),C[2]);\nconst h=L.crossfade.seconds/2,e=F.ease.inOut;dev.rotation.set(0,ROT*e(F.remap(T,s3.start,s3.end-h,0,1))*(1-e(F.remap(T,s3.end-h,s3.end+h,0,1))),0);\nconst g=F.screenMesh.material;if(!g.isMeshStandardMaterial)return;if(!g.emissiveMap&&g.map){g.emissiveMap=g.map;g.needsUpdate=true}\ng.emissive.set(g.emissiveMap?'#ffffff':P.screenGround);g.color.set('#000000');\n}});\nF.test('device: visible triangles <= max and lights <= max',()=>{let t=0,n=0;\nF.world.traverseVisible(o=>{if(o.isLight)n++;if(o.isMesh&&o.geometry){const g=o.geometry,c=g.index?g.index.count:g.attributes.position.count;t+=c/3*(o.isInstancedMesh?o.count:1)}});\nreturn{ok:t<=L.maxTriangles&&n<=L.maxLights,detail:t+' triangles, '+n+' lights'}});\n})();\n",
