      "output": "(()=>{const F=window.F,X=F.THREE,S=F.SHEET,P=S.palette,G=S.screenGraph,D=S.look.device,[CW,CH]=D.screenCanvas,sh=S.shots,ty=sh.find(s=>s.module==='type'),t0=sh[0].start,t1=ty?ty.start:F.LENGTH;\nconst cv=document.createElement('canvas');cv.width=CW;cv.height=CH;const c=cv.getContext('2d');let nt=0;c.fillText=c.strokeText=function(){nt++};\nconst tx=new X.CanvasTexture(cv);tx.colorSpace=X.SRGBColorSpace;tx.anisotropy=8;\nconst [cw,ch]=G.card,R=G.radius,[bw,bh]=G.bar,N={},B=F.BEAT,cl=F.clamp;G.nodes.forEach(n=>N[n.id]=n);\nconst pu=G.pulses,lit=G.wires.map(()=>Infinity);pu.wires.forEach(j=>lit[j]=pu.from);G.handoffs.forEach(h=>h.wires.forEach(j=>lit[j]=Math.min(lit[j],h.t)));\nconst W=G.wires.map(([a,b])=>{const A=N[a],Z=N[b],x0=A.x+cw,y0=A.y+ch/2,x3=Z.x,y3=Z.y+ch/2,d=(x3-x0)/2;return{A,Z,p:[x0,y0,x0+d,y0,x3-d,y3,x3,y3]}});\nconst bz=(p,k)=>{const u=1-k;return[0,1].map(i=>u*u*u*p[i]+3*u*u*k*p[2+i]+3*u*k*k*p[4+i]+k*k*k*p[6+i])};\nconst rr=(x,y,w,h,r)=>{r=Math.min(r,w/2,h/2);c.beginPath();c.moveTo(x+r,y);c.arcTo(x+w,y,x+w,y+h,r);c.arcTo(x+w,y+h,x,y+h,r);c.arcTo(x,y+h,x,y,r);c.arcTo(x,y,x+w,y,r);c.closePath()};\nconst st=(n,T)=>T<n.run[0]?0:T<n.run[1]?1:2,SC=[P.idle,P.running,P.done];\nconst seg=(p,k0,k1)=>{c.beginPath();for(let i=0;i<=24;i++){const q=bz(p,F.lerp(k0,k1,i/24));i?c.lineTo(q[0],q[1]):c.moveTo(q[0],q[1])}c.stroke()};\nconst dot=(x,y,r,col,a)=>{c.globalAlpha=a;c.fillStyle=col;c.beginPath();c.arc(x,y,r,0,7);c.fill()};\nconst glow=(x,y,a)=>{const g=c.createRadialGradient(x,y,0,x,y,34);g.addColorStop(0,P.awwoBlue);g.addColorStop(1,'rgba(47,129,247,0)');c.globalAlpha=a;c.fillStyle=g;c.beginPath();c.arc(x,y,34,0,7);c.fill();dot(x,y,12,P.awwoBlue,a);dot(x,y,6,P.ink,a)};\nfunction bg(){c.globalAlpha=1;c.fillStyle=P.screenGround;c.fillRect(0,0,CW,CH);c.fillStyle=P.cardEdge;c.globalAlpha=.55;for(let y=100;y<CH;y+=40)for(let x=40;x<CW;x+=40)c.fillRect(x-1.5,y-1.5,3,3);\nc.globalAlpha=1;c.fillStyle=P.card;c.fillRect(0,0,CW,64);c.fillStyle=P.cardEdge;c.fillRect(0,63,CW,2);\n[[28,22,20,20,6,P.awwoBlue],[64,25,120,14,7,P.idle],[200,25,80,14,7,P.cardEdge],[CW-180,20,150,24,12,P.cardEdge]].forEach(b=>{c.fillStyle=b[5];rr(b[0],b[1],b[2],b[3],b[4]);c.fill()})}\nfunction wires(T){c.lineCap='round';W.forEach((w,j)=>{const ta=Math.max(w.A.appear,w.Z.appear)+.15,k=F.win(T,ta,.3);if(k<=0)return;const L=T>=lit[j];\nc.globalAlpha=1;c.strokeStyle=L?P.awwoBlue:P.wire;c.lineWidth=L?5:3;seg(w.p,0,k);\nif(st(w.A,T)==1&&!L){const q=((T-w.A.run[0])/(2*B))%1;c.strokeStyle=P.awwoBlue;c.lineWidth=5;c.globalAlpha=.7*k;seg(w.p,Math.max(0,q-.18),q)}});\nW.forEach((w,j)=>{const ts=[];if(pu.wires.includes(j))for(let t=pu.from;t<pu.until-1e-6;t+=pu.everyBeats*B)ts.push(t);G.handoffs.forEach(h=>h.wires.includes(j)&&ts.push(h.t));\nts.forEach(t=>{const k=(T-t)/pu.travel;if(k<0||k>1)return;const e=F.ease.inOut(k),q=bz(w.p,e);glow(q[0],q[1],Math.min(1,(1-k)*4,k*8+.3))})});c.globalAlpha=1}\nfunction cards(T){G.nodes.forEach((n,i)=>{const k=cl((T-n.appear)/.3,0,1);if(k<=0)return;const s=.9+.1*F.ease.overshoot(k),s0=st(n,T),cx=n.x+cw/2,cy=n.y+ch/2;\nc.save();c.translate(cx,cy);c.scale(s,s);c.translate(-cw/2,-ch/2);c.globalAlpha=Math.min(1,k*2);\nif(s0==1){c.shadowColor=P.running;c.shadowBlur=26}c.fillStyle=P.card;rr(0,0,cw,ch,R);c.fill();c.shadowBlur=0;\nc.lineWidth=s0?3:2;c.strokeStyle=s0==1?P.running:s0==2?P.done:P.cardEdge;rr(0,0,cw,ch,R);c.stroke();\nc.fillStyle=P.idle;rr(30,30,130+(i*37)%60,16,8);c.fill();c.fillStyle=P.cardEdge;rr(30,60,90+(i*53)%80,12,6);c.fill();\nconst dc=SC[s0],ph=s0==1?.5+.5*Math.cos((T-n.run[0])/B*Math.PI*2):0,dx=cw-30-G.dot/2,dy=38;\nif(s0==1){c.globalAlpha*=.35*(1-ph*.6);c.fillStyle=dc;c.beginPath();c.arc(dx,dy,G.dot*(1+ph*.8),0,7);c.fill();c.globalAlpha=Math.min(1,k*2)}\nc.fillStyle=dc;c.beginPath();c.arc(dx,dy,G.dot/2+2,0,7);c.fill();\nconst bx=(cw-bw)/2,by=ch-30-bh,f=cl((T-n.run[0])/(n.run[1]-n.run[0]),0,1);c.fillStyle=P.screenGround;rr(bx,by,bw,bh,bh/2);c.fill();\nif(f>0){c.fillStyle=s0==2?P.done:P.running;rr(bx,by,Math.max(bh,bw*f),bh,bh/2);c.fill()}\nc.restore()});\nconst g=cl((T-G.allGreen)/.6,0,1);if(g>0&&g<1){c.globalAlpha=(1-g)*.5;c.strokeStyle=P.done;c.lineWidth=4;G.nodes.forEach(n=>{const e=10+g*30;rr(n.x-e,n.y-e,cw+2*e,ch+2*e,R+e);c.stroke()})}\nc.globalAlpha=1}\nconst run=T=>{const ns=G.nodes;let f=0;ns.forEach(n=>f+=cl((T-n.run[0])/(n.run[1]-n.run[0]),0,1));const y=CH-34;c.globalAlpha=Math.min(1,F.win(T,ns[0].appear,.3)+.0);c.fillStyle=P.card;rr(40,y-10,CW-80,20,10);c.fill();\nif(f>0){c.fillStyle=T>=G.allGreen?P.done:P.awwoBlue;rr(40,y-10,Math.max(20,(CW-80)*f/ns.length),20,10);c.fill()}c.globalAlpha=1};\nconst draw=T=>{bg();run(T);wires(T);cards(T);tx.needsUpdate=true};\nlet fb,lm;const bind=()=>{const m=F.screenMesh;if(!m||!m.material||lm===m)return;lm=m;[].concat(m.material).forEach(q=>{q.map=tx;if(\"emissiveMap\"in q){q.emissiveMap=tx;if(q.emissive.getHex()===0)q.emissive.set(16777215)}q.needsUpdate=true})};\nF.scene('screen',{start:t0,end:t1,setup(r){const[w,h]=D.screenSize,[x,y,z]=D.center;fb=new X.Mesh(new X.PlaneGeometry(w,h),new X.MeshBasicMaterial({map:tx,toneMapped:false}));fb.position.set(x,y,z+D.depth/2+.002);r.add(fb);draw(t0);bind()},\nupdate(T){bind();fb.visible=!F.screenMesh;draw(T)}});\nF.test('screen never draws text',()=>{nt=0;[3,4.8,7.5,10.5,14].forEach(draw);return{ok:nt===0,detail:'text calls on screen canvas: '+nt}});\nF.test('screen texture lit',()=>{draw(10.5);const d=c.getImageData(CW*.35|0,CH*.45|0,8,8).data;return{ok:d[3]===255,detail:'pixel '+d[0]+','+d[1]+','+d[2]}})})();\n",
