      "output": "(() => {\nconst F = window.F, S = F.SHEET, sh = S.shots, cf = (S.look && S.look.crossfade) || {}, H2 = (cf.seconds || (cf.frames || 6) / F.FPS) / 2, DIP = 0.12, E = F.ease.inOut, L = F.lerp;\nconst mix = (a, b, k) => a.map((v, i) => L(v, b[i], k));\nconst idx = T => { let i = 0; while (i < sh.length - 1 && T >= sh[i + 1].start) i++; return i; };\nconst pose = (i, T) => { const s = sh[i], c = s.camera, k = E(F.clamp((T - s.start) / (s.end - s.start), 0, 1)); return { position: mix(c.from, c.to, k), target: c.lookAt.slice(), fov: c.fov }; };\nconst near = T => { for (let i = 1; i < sh.length; i++) { const d = T - sh[i].start; if (Math.abs(d) < H2) return { i, d }; } return null; };\nconst cam = T => {\n  const n = near(T);\n  if (!n) return pose(idx(T), T);\n  const a = pose(n.i - 1, T), b = pose(n.i, T), k = E((n.d + H2) / (2 * H2));\n  return { position: mix(a.position, b.position, k), target: mix(a.target, b.target, k), fov: L(a.fov, b.fov, k) };\n};\nF.cam = cam;\nconst dip = T => { const n = near(T); return n ? DIP * (1 - Math.abs(n.d) / H2) : 0; };\nconst rig = (root, nm) => { const o = new F.THREE.Object3D(); o.name = nm; root.add(o); return o; };\nconst mine = sh.filter(s => s.module === 'shots');\nmine.forEach(s => {\n  let o;\n  F.scene(s.id, { start: s.start, end: s.end, setup(root) { o = rig(root, 'rig-' + s.id); }, update(T) { const c = cam(T); o.position.set(c.target[0], c.target[1], c.target[2]); } });\n});\nlet g;\nF.scene('crossfade', { start: sh[0].start, end: sh[sh.length - 1].end, setup(root) { g = rig(root, 'dip'); }, update(T, l, info) {\n  const a = dip(T); g.position.set(0, 0, a);\n  if (a <= 0) return;\n  const x = (info && info.ctx2d) || (F.overlay && F.overlay.getContext('2d'));\n  if (!x) return;\n  x.save(); x.globalAlpha = a; x.fillStyle = S.palette.ground; x.fillRect(0, 0, F.W, F.H); x.restore();\n} });\nF.test('shots: camera finite, fov 28-32, smooth inside shots', () => {\n  let bad = [], mx = 0, p = null;\n  for (let f = 0; f < F.LENGTH * F.FPS; f++) {\n    const T = f / F.FPS, c = cam(T), v = [...c.position, ...c.target, c.fov];\n    if (v.some(z => !isFinite(z)) || c.fov < 28 || c.fov > 32) bad.push(T);\n    if (p && !near(T) && !near(T - 1 / F.FPS) && idx(T) === idx(T - 1 / F.FPS)) mx = Math.max(mx, Math.hypot(...c.position.map((z, i) => z - p[i])));\n    p = c.position;\n  }\n  return { ok: !bad.length && mx < 0.1, detail: 'bad ' + bad.length + ', max step ' + mx.toFixed(4) };\n});\nF.test('shots: crossfade dip at most 12 % at every boundary', () => {\n  let ok = true, d = [];\n  for (let i = 1; i < sh.length; i++) { const b = sh[i].start, a = dip(b); d.push(a.toFixed(2)); if (!(a > 0 && a <= DIP) || dip(b - 2 * H2) || dip(b + 2 * H2)) ok = false; }\n  return { ok, detail: d.join(' ') };\n});\n})();\n",
