      "output": "(()=>{const F=window.F,S=F.SHEET,P=S.palette,O=S.fonts,K=S.shots,M=S.look.safeMargin||.05,X=(S.look.crossfade||{}).seconds||.2;\nconst R={poster:[O.display,O.displayWeight,O.displaySizeOfH,P.ink],caption:[O.text,O.textWeight,O.textSizeOfH,P.ink],label:[O.text,O.textWeight,O.smallSizeOfH,P.inkDim]};\nconst L=s=>(s.words||[]).map(w=>Object.assign({s},w)),E=K.filter(s=>s.module==='type'),LW=K.filter(s=>s.module!=='type').flatMap(L);\nconst al=(w,T)=>{if(T<w.at||T>=w.until)return[0,0];const i=w.at===w.s.start?1:F.ease.arrive((T-w.at)/.4),o=w.until>=F.LENGTH?1:1-F.ease.leave((T-w.until+.3)/.3);return[Math.min(i,o),(1-i)*.02]};\nconst dw=(c,T,W,H,ws)=>{for(const w of ws){const[k,r]=al(w,T);if(!(k>.002))continue;const[f,g,z,col]=R[w.role]||R.caption,x=w.x*W,y=(w.y+r)*H,mw=w.align==='center'?2*Math.min(x-M*W,(1-M)*W-x):(1-M)*W-x;F.text(c,w.text,x,y,{size:z*H,font:f,weight:g,color:col,align:w.align||'left',baseline:'middle',tracking:w.role==='poster'?-.01:0,maxWidth:mw*.97,alpha:k})}};\nconst cx=i=>i.ctx2d||F.overlay.getContext('2d'),wh=i=>[i.W||F.W,i.H||F.H];\nconst fill=(c,W,H,a)=>{c.save();c.globalAlpha=a;c.fillStyle=P.endCard||P.ground;c.fillRect(0,0,W,H);c.restore()};\nconst e=E[0],dot=r=>r.add(new F.THREE.Object3D());\nF.scene('type',{start:K[0].start,end:K[K.length-1].end,setup:dot,update(T,l,i){const c=cx(i),[W,H]=wh(i);if(e&&T<e.start){const a=F.win(T,e.start-X/2,X/2);if(a>0)fill(c,W,H,a)}dw(c,T,W,H,LW)}});\nlet A,B;\nE.forEach(s=>{const ws=L(s);F.scene(s.id,{start:s.start,end:s.end,setup(r){dot(r);A=new Path2D(\"M61 34C80 26 99 33 109 51L198 205H146L64 64L48 92L113 205H62L11 115C4 103 5 89 12 77L35 48C42 43 50 38 61 34Z\");B=new Path2D(\"M151 34C170 26 191 35 200 51L246 133C253 145 252 157 245 169L224 205L195 155L158 91L143 118L118 75L137 45C141 40 146 37 151 34Z\")},update(T,l,i){const c=cx(i),[W,H]=wh(i);fill(c,W,H,1);const k=.28*H/200.48;c.save();c.globalAlpha=1;c.shadowBlur=0;c.shadowColor='rgba(0,0,0,0)';c.translate(W/2-128.22*k,.18*H-29.12*k);c.scale(k,k);c.translate(10,0);c.scale(.92,1.12);c.fillStyle=P.awwoBlue;c.fill(A);c.fill(B);c.restore();dw(c,T,W,H,ws)}})});\nF.test('type: every on-screen string is in F.SHEET.facts',()=>{const b=LW.concat(E.flatMap(L)).map(w=>w.text).concat((F.boxes||[]).map(x=>x.words)).filter(t=>!S.facts.includes(t));return{ok:!b.length,detail:b.length?'not in facts: '+b.join(' | '):'all words in facts'}});\n})();\n",
